import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Namespaces and Identifiers","description":"","frontmatter":{},"headers":[],"relativePath":"your-first-al-programs/namespaces-and-identifiers.md","filePath":"your-first-al-programs/namespaces-and-identifiers.md"}`),a={name:`your-first-al-programs/namespaces-and-identifiers.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="namespaces-and-identifiers" tabindex="-1">Namespaces and Identifiers <a class="header-anchor" href="#namespaces-and-identifiers" aria-label="Permalink to “Namespaces and Identifiers”">​</a></h1><h2 id="what-are-identifiers" tabindex="-1">What Are Identifiers <a class="header-anchor" href="#what-are-identifiers" aria-label="Permalink to “What Are Identifiers”">​</a></h2><p>An <strong>identifier</strong> is a name used to identify something in your code, such as a variable, procedure, table, page, or codeunit.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    CustomerName: Text[100];</span></span>
<span class="line"><span>    TotalAmount: Decimal;</span></span></code></pre></div><p>Here, <code>CustomerName</code> and <code>TotalAmount</code> are identifiers because they name variables.</p><p>Identifiers make it possible to refer to specific elements in your code.</p><h3 id="naming-rules" tabindex="-1">Naming Rules <a class="header-anchor" href="#naming-rules" aria-label="Permalink to “Naming Rules”">​</a></h3><p>When creating identifiers in AL:</p><ul><li>Names are case-insensitive. For example, <code>CustomerName</code> and <code>CUSTOMERNAME</code> refer to the same identifier.</li><li>Names generally start with a letter or underscore.</li><li>Names can contain letters, digits, and underscores.</li><li>Reserved keywords, such as <code>begin</code>, cannot be used as ordinary identifiers.</li><li>Names containing spaces or special characters must be enclosed in double quotation marks.</li></ul><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    CustomerName: Text[100];</span></span>
<span class="line"><span>    &quot;Customer No.&quot;: Code[20];</span></span></code></pre></div><p>Notice that <code>&quot;Customer No.&quot;</code> uses double quotation marks because its name contains a space and a period.</p><h2 id="what-is-a-namespace" tabindex="-1">What Is a Namespace? <a class="header-anchor" href="#what-is-a-namespace" aria-label="Permalink to “What Is a Namespace?”">​</a></h2><p>A <strong>namespace</strong> is a way of organizing AL objects into logical groups and avoiding naming conflicts.</p><p>Imagine two extensions developed by different companies. Both developers create a codeunit called <code>CustomerManager</code>.</p><p>Namespaces help distinguish between these objects by giving each one a qualified name.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace CompanyA.Sales;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codeunit 50100 CustomerManager</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Sales-related functionality</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Another extension could have:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace CompanyB.Inventory;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codeunit 50100 CustomerManager</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Inventory-related functionality</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Although both codeunits share the same name, their namespaces distinguish them.</p><p>Think of namespaces like folders on your computer: two folders can contain files with the same name because their paths are different.</p><p><strong>Note:</strong> AL namespaces are supported in Business Central 2023 release wave 2 (version 23) and later.</p><h2 id="declaring-a-namespace" tabindex="-1">Declaring a Namespace <a class="header-anchor" href="#declaring-a-namespace" aria-label="Permalink to “Declaring a Namespace”">​</a></h2><p>Use the <code>namespace</code> keyword at the beginning of an AL file to declare its namespace.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace MyCompany.Sales;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codeunit 50100 SalesManager</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Sales-related functionality</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>In this example, <code>MyCompany.Sales</code> is the namespace, while <code>SalesManager</code> is the codeunit name.</p><p>Namespaces can contain multiple levels, separated by periods (<code>.</code>), to represent logical groupings.</p><p>For example:</p><ul><li><code>MyCompany</code> — identifies the organization.</li><li><code>MyCompany.Sales</code> — groups sales-related functionality.</li><li><code>MyCompany.Sales.Reporting</code> — groups sales reporting functionality.</li></ul><p>These are naming conventions for organizing code; the periods do not represent physical folders.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>The first part of a namespace should be tied to the developing organization or ann individual followed by a product name and logical grouping with inn the product. For example <code>namespace Acme.Products.Reports</code></p></div><h2 id="the-using-directive" tabindex="-1">The <code>using</code> Directive <a class="header-anchor" href="#the-using-directive" aria-label="Permalink to “The using Directive”">​</a></h2><p>When you need to reference an object from another namespace, you can use its fully qualified name or import its namespace using the <code>using</code> directive.</p><p>A <strong>fully qualified name</strong> includes the namespace and the object&#39;s name.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace MyCompany.Sales;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using MyCompany.Inventory;</span></span></code></pre></div><p>The <code>using</code> directive allows you to reference objects in <code>MyCompany.Inventory</code> without repeatedly specifying the entire namespace.</p><p>It must appear after the namespace declaration and before the object declaration.</p><p>Think of <code>using</code> as telling AL which additional namespace to look in when resolving object names.</p><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-namespaces-overview" target="_blank" rel="noreferrer">Namespaces in AL</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-al-variables" target="_blank" rel="noreferrer">AL Variables and Naming Rules</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-namespaces-structure" target="_blank" rel="noreferrer">Adopting Namespaces in AL</a></li></ul><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to “Key Takeaway”">​</a></h2><p><strong>Identifiers name elements in your code, while namespaces organize AL objects and help distinguish between objects with the same name.</strong> The <code>namespace</code> keyword declares a namespace, and the <code>using</code> directive makes objects from another namespace easier to reference.\`\`\`</p>`,45)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};